after.content:
        JsonNode second = harness.request(101, "session/list", Map.of("cursor", cursor));
        assertEquals(1, second.path("result").path("sessions").size());
        assertTrue(!second.path("result").has("nextCursor"));
        JsonNode foreignFilter = harness.request(102, "session/list", Map.of("cursor", cursor, "cwd", "other"));
        assertEquals(-32602, foreignFilter.path("error").path("code").asInt());
        assertEquals("protocol.invalid_message", foreignFilter.path("error").path("data").path("code").asText());
        assertEquals(-32602, harness.request(103, "session/list", Map.of("cursor", "invalid"))
                .path("error").path("code").asInt());
    }
}
